          intro: '<p>Drag the glass toolbar over the photo, the text, the colored tiles and the bright and dark blocks (or focus it and use the arrow keys). Switch between Regular and Clear, change the blur and tint, then turn on the glass-on-glass mistake. The legibility meter computes the contrast between the icons and what is really behind them, using a Swift function compiled to WebAssembly.</p>',
