          title: 'Safe areas and margins',
          body: '<p>A <strong>safe area</strong> is the part of the screen nothing covers: below the status bar and Dynamic Island, above the home indicator (34 pt on Face ID iPhones). The top inset changes from model to model, so never hard-code it; SwiftUI keeps content inside the safe area for you.</p><p><strong>Layout margins</strong> are the standard gap between content and the screen edge: 16 pt on iPhone in portrait, 20 pt on iPad and some wider layouts. Lists, navigation titles and a bare <code>.padding()</code> all line up on that margin.</p>',
