              answer: 2,
              explain: '<p>Creating an event is a self-contained task with a clear end, which is what sheets are for. Pushing it makes it look like a deeper level, so Back is ambiguous: saved or discarded? A tab turns an action into a place, and replacing the screen removes the way out.</p>',
