          kind: 'concept',
          title: 'Words are interface too',
          body: '<p>Labels, titles and messages are designed just like layout and color. Apple’s writing guidance comes down to being clear, concise and helpful, in the voice of a calm expert who is on the user’s side.</p>',
          points: [
            { term: 'Buttons are verbs', text: 'Name the action: “Save Trip”, “Delete Photo”, “Try Again”. “OK”, “Yes” and “Submit” force people to reread the question to know what will happen.' },
            { term: 'Errors answer three questions', text: 'What happened, why (when it helps), and what to do now: “Couldn’t Load Trips. Your iPhone is offline. Check Wi-Fi, then try again.”' },
            { term: 'No blame, no codes', text: 'Write “Couldn’t save the card” rather than “You entered invalid data”. Keep codes such as -1009 for your logs, not for people.' },
            { term: 'One word per idea', text: 'If the tab says Trips, never call them Journeys elsewhere. Consistent terms make an app predictable.' },
            { term: 'Front-load meaning', text: 'Put the important words first and cut filler such as “please”, “successfully” and “an error has occurred”.' },
          ],
          callout: { tone: 'tip', title: 'Read it out loud', html: '<p>If a sentence would sound strange said to a friend, rewrite it. Reading aloud also previews what VoiceOver users will hear.</p>' },
